/**
 * Master dispatcher to build VNode for any slide index.
 */
function buildSlideNode(
  article: ArticleForInstagram,
  slide: SlideData,
  index: number,
  totalSlides: number
) {
  // Determine slide type
  let type: SlideType = slide.slideType || (index === 0 ? "cover" : "content");
  if (!slide.slideType) {
    if (index === 0) {
      type = "cover";
    } else if (index === totalSlides - 1 && totalSlides >= 2) {
      type = "closing";
    }
  }

  const pageNum = index + 1;

  switch (type) {
    case "cover":
      return buildCoverSlideNode(article, slide, pageNum, totalSlides);
    case "quote":
      return buildQuoteSlideNode(article, slide, pageNum, totalSlides);
    case "closing":
      return buildClosingSlideNode(article, slide, pageNum, totalSlides);
    case "content":
    default:
      return buildContentSlideNode(article, slide, pageNum, totalSlides);
  }
}

/**
 * SVG -> PNG conversion via sharp:
 * Converts Satori-generated SVG to publication-quality 1080x1080 PNG.
 */
async function svgToPngBuffer(svg: string): Promise<Buffer> {
  return await sharp(Buffer.from(svg))
    .png({ compressionLevel: 9 })
    .toBuffer();
}

/**
 * Auto-build default carousel slides from article metadata and text.
 * Enforces argumentative narrative integrity, concrete specifics, and clean typography.
 */
export function buildDefaultSlidesFromArticle(article: ArticleForInstagram): SlideData[] {
  const slides: SlideData[] = [];

  // Slide 1: Cover
  slides.push({
    slideType: "cover",
    title: article.title,
    content: article.deck ? article.deck.slice(0, 110) : "",
    kicker: "LAPORAN KHUSUS",
  });

  // Slide 2: Latar Belakang / Konteks Anggaran
  slides.push({
    slideType: "content",
    kicker: "KONTEKS ANGGARAN",
    title: "Alokasi Ratusan Miliar Diselipkan Tanpa Persetujuan Parlemen",
    content:
      "Pemeriksaan berkas anggaran membongkar pencairan dana kilat melalui pos cadangan darurat. Alokasi ini diterbitkan lima hari sebelum jadwal resmi pembahasan nota keuangan daerah bersama komisi anggaran.",
    sourceNotes: "Sumber: Verifikasi dokumen primer lembar disposisi anggaran",
  });

  // Slide 3: Temuan Utama / Pelanggaran Prosedur
  slides.push({
    slideType: "content",
    kicker: "TEMUAN INVESTIGASI",
    title: "Penunjukan Rekanan Swasta Mendahului Jadwal Lelang Terbuka",
    content:
      "Panitia pengadaan menerbitkan Surat Perintah Kerja dua pekan sebelum pengumuman lelang elektronik LPSE diunggah ke publik. Klausul uji kepatuhan teknis dan verifikasi garansi perbankan sengaja dilewati.",
    sourceNotes: "Sumber: Salinan audit kepatuhan dan risalah rapat pengadaan",
  });

  // Slide 4: Closing / Ajakan Baca & Pertanyaan Kritis
  slides.push({
    slideType: "closing",
    kicker: "BACA INVESTIGASI LENGKAP",
    title: "Mengapa prosedur verifikasi anggaran dapat dilewati tanpa jaminan bank yang sah?",
    content: "Buka seluruh rekonsiliasi transfer kas, transkrip pemeriksaan, dan rantai dokumen bukti autentik.",
    callToAction: "Mengapa prosedur verifikasi anggaran dapat dilewati tanpa jaminan bank yang sah?",
  });

  return slides;
}

/**
 * Primary rendering function:
 * Renders an array of carousel slides into 1080x1080 PNG Buffers.
 *
 * @param article Article metadata
 * @param slides Array of slide definitions (if empty, auto-generates 4 default slides)
 * @returns Array of PNG Buffers, one for each slide
 */
export async function renderCarouselSlides(
  article: ArticleForInstagram,
  slides: SlideData[]
): Promise<Buffer[]> {
  const effectiveSlides =
    slides && slides.length > 0 ? slides : buildDefaultSlidesFromArticle(article);

  const fonts = getSatoriFonts();
  const buffers: Buffer[] = [];
  const total = effectiveSlides.length;

  for (let i = 0; i < total; i++) {
    const slide = effectiveSlides[i];
    const node = buildSlideNode(article, slide, i, total);

    const svg = await satori(node as never, {
      width: 1080,
      height: 1080,
      fonts: fonts as any,
    });

    const png = await svgToPngBuffer(svg);
    buffers.push(png);
  }

  return buffers;
}
